--
-- Table structure for table `head_kpi_assessments`
--

DROP TABLE IF EXISTS `head_kpi_assessments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `head_kpi_assessments` (
  `kpi_id` int NOT NULL AUTO_INCREMENT,
  `period_month` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Januari',
  `period_year` int DEFAULT '2026',
  `period_key` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '2026-01',
  `location_id` int DEFAULT NULL,
  `assessor_user_id` int DEFAULT NULL,
  `evaluated_user_id` int DEFAULT NULL,
  `indicator_no` int NOT NULL,
  `aspect_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `indicator_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_standard` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `score_val` int NOT NULL DEFAULT '1',
  `weight_pct` decimal(5,2) NOT NULL,
  `weighted_score` decimal(5,2) GENERATED ALWAYS AS (((`score_val` * `weight_pct`) / 5)) STORED,
  `audit_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `version` int NOT NULL DEFAULT '1',
  `submitted_at` datetime DEFAULT NULL,
  `approved_by` int DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `approval_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
